import { readFileSync } from 'node:fs'
import { total } from '../src/cart.js'
const spec = JSON.parse(Buffer.from(readFileSync(new URL('./contract.b64', import.meta.url), 'utf8'), 'base64').toString())
const got = total(spec.input)
if (typeof got !== spec.type) { console.error(`billing contract v1: total() must return a ${spec.type}: ${spec.why}`); process.exit(1) }
console.log('billing contract v1 ok')
